const families={
  average:{name:'The Moreaus',tagline:'A little ambition goes a long way.',icon:'✦',letter:'M',neighborhood:'Maplewood',funds:24800,income:4200,home:385000,color:'#d8a16c',homeStyle:'starter',members:[{name:'Maya Moreau',role:'Community nurse',emoji:'👩🏻‍🦰',status:'At home',initial:'M'},{name:'Leo Moreau',role:'Junior designer',emoji:'👨🏽',status:'At work',initial:'L'},{name:'Nina Moreau',role:'Big dreamer · 8',emoji:'👧🏻',status:'Playing',initial:'N'}],goal:'Make this house a home',goalSub:'Your first chapter',wealth:27,job:'Junior designer',business:'No business yet',vehicle:'Used hatchback',insurance:'Basic home & health',plane:'Commercial flights'},
  rich:{name:'The Parkers',tagline:'Good taste. Bigger possibilities.',icon:'❋',letter:'P',neighborhood:'Cedar Crest',funds:487500,income:28900,home:2450000,color:'#9874c0',homeStyle:'estate',members:[{name:'Olivia Parker',role:'Creative director',emoji:'👩🏼',status:'At home',initial:'O'},{name:'James Parker',role:'Investment partner',emoji:'👨🏻‍💼',status:'At work',initial:'J'},{name:'Aria Parker',role:'Curious soul · 12',emoji:'👩🏽',status:'Reading',initial:'A'}],goal:'Grow the family portfolio',goalSub:'Building something lasting',wealth:68,job:'Creative director',business:'Parker Studio · 12 staff',vehicle:'Electric grand tourer',insurance:'Premium home, health & auto',plane:'Private charter'},
  ultra:{name:'The Ashfords',tagline:'A world of possibility, by design.',icon:'✧',letter:'A',neighborhood:'The Heights',funds:24800000,income:680000,home:78500000,color:'#54a99b',homeStyle:'mansion',members:[{name:'Eleanor Ashford',role:'Philanthropist',emoji:'👩🏻‍🦳',status:'At home',initial:'E'},{name:'Alexander Ashford',role:'Global CEO',emoji:'👨🏼‍💼',status:'At work',initial:'A'},{name:'Sophie Ashford',role:'Future founder · 16',emoji:'👩🏼',status:'Creating',initial:'S'}],goal:'Leave a brighter legacy',goalSub:'More than a family fortune',wealth:94,job:'Global CEO',business:'Ashford Group · 4,800 staff',vehicle:'Luxury car collection',insurance:'Global all-assets protection',plane:'Family-owned jet'}
};
const destinations=[['Singapore','🇸🇬','$1,280','Tropical city garden'],['Tokyo','🇯🇵','$1,540','Neon nights & quiet mornings'],['Los Angeles','🇺🇸','$1,160','A little California sunshine'],['Doha','🇶🇦','$1,430','Art, architecture & the sea'],['Dubai','🇦🇪','$1,380','Desert days, city lights'],['London','🇬🇧','$980','A classic city escape'],['Paris','🇫🇷','$1,050','Slow days on the Seine'],['Milan','🇮🇹','$1,120','Design, style & espresso'],['New York','🇺🇸','$1,090','The city that never sleeps'],['Zurich','🇨🇭','$1,190','Mountain air & lake views']];
const classes=[{name:'Economy',icon:'◷',mult:1,copy:'A comfy, clever choice'},{name:'Business',icon:'◇',mult:2.7,copy:'Room to stretch out'},{name:'First class',icon:'✦',mult:5.4,copy:'Arrive feeling wonderful'}];
const state={family:'average',money:24800,day:14,month:4,year:1,zoom:1,view:0,scene:'home',destination:null,travelClass:0,tripDays:5,goalProgress:35,mood:82,peopleExtra:[],careerLevel:0,businessLevel:0,insuranceLevel:0,vehicleLevel:0};
const $=s=>document.querySelector(s), world=$('#world'),ctx=world.getContext('2d');let canvasW=900,canvasH=470,toastTimer;
const family=()=>families[state.family];
const fmt=n=>'$'+Math.round(n).toLocaleString('en-US');
function sync(){let f=family();$('#family-name').textContent=f.name;$('#family-tagline').textContent=f.tagline;$('#family-icon').textContent=f.icon;$('#family-avatar').textContent=f.letter;$('#caption-avatar').textContent=f.letter;$('#money-value').textContent=fmt(state.money);$('#income-value').textContent=fmt(f.income);$('#home-value').textContent=fmt(f.home);$('#neighborhood-value').textContent=f.neighborhood;$('#wealth-progress').style.width=Math.max(9,Math.min(100,f.wealth+(state.money-f.funds)/Math.max(f.funds,1)*18))+'%';$('#scene-family-title').textContent=f.name.replace('The ','')+' Family Home';$('#scene-family-sub').textContent=state.scene==='home'?`${f.neighborhood} · ${f.homeStyle==='starter'?'A cozy place to grow':f.homeStyle==='estate'?'A little room for everything':'A home above it all'}`:`${state.destination||'Somewhere lovely'} · making memories`;$('#goal-title').textContent=f.goal;$('#goal-subtitle').textContent=f.goalSub;$('#goal-progress').style.width=state.goalProgress+'%';$('#goal-percent').textContent=state.goalProgress+'%';$('#people-count').textContent='· '+(f.members.length+state.peopleExtra.length);$('#scene-location').textContent=state.scene==='home'?`${f.neighborhood.toUpperCase()} · HOME`:`${state.destination?.toUpperCase()||'YOUR GETAWAY'} · DAY ${Math.min(state.day,5)}`;$('#today-event').textContent=state.scene==='home'?'Slow morning at home':'A day to remember';$('#today-detail').textContent=state.scene==='home'?'A good day to make a plan':`Exploring ${state.destination||'somewhere new'}`;$('#work-event').textContent=state.scene==='home'?'Work & opportunity':'Little moments, big memories';$('#work-detail').textContent=state.scene==='home'?`${f.job} · ${f.business}`:'Take it all in, one day at a time';$('#date-label').textContent=`${['SUNDAY','MONDAY','TUESDAY','WEDNESDAY','THURSDAY','FRIDAY','SATURDAY'][(state.day+1)%7]}, ${['','JANUARY','FEBRUARY','MARCH','APRIL','MAY','JUNE','JULY','AUGUST','SEPTEMBER','OCTOBER','NOVEMBER','DECEMBER'][state.month]} ${state.day}`;$('#season-label').textContent=`${state.month<3||state.month>11?'WINTER':state.month<6?'SPRING':state.month<9?'SUMMER':'AUTUMN'} · YEAR ${state.year}`;$('#greeting').innerHTML=state.scene==='home'?'A fresh start, <em>together.</em>':`Hello, <em>${state.destination||'traveler'}.</em>`;$('#sub-greeting').textContent=state.scene==='home'?'Your home is waiting. What will today bring?':'A change of scene can change everything.';$('#next-day').innerHTML=state.scene==='home'?'Next day <span>→</span>':'Next vacation day <span>→</span>';renderPeople();drawScene()}
function renderPeople(){let arr=family().members.concat(state.peopleExtra);$('#people-list').innerHTML=arr.map((p,i)=>`<div class="person-row"><span class="person-avatar ${['a','b','c','d'][i%4]}">${p.emoji}</span><div class="person-details"><b>${p.name}</b><small>${p.role}</small></div><span class="person-status ${p.status==='At work'?'work':''}">${p.status}</span></div>`).join('')}
function toast(msg){let t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2500)}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal-backdrop').classList.add('open');$('#modal-backdrop').setAttribute('aria-hidden','false')}
function closeModal(){$('#modal-backdrop').classList.remove('open');$('#modal-backdrop').setAttribute('aria-hidden','true')}
function moneyChange(n,msg){state.money=Math.max(0,state.money+n);sync();if(msg)toast(msg)}
function dollars(str){return Number(String(str).replace(/[^0-9]/g,''))||0}

function poly(points,fill,stroke){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
function ellipse(x,y,rx,ry,color){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill()}
function rr(x,y,w,h,r,color){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=color;ctx.fill()}
function line(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function text(s,x,y,size,color,weight='500',align='center'){ctx.fillStyle=color;ctx.font=`${weight} ${size}px "DM Sans", sans-serif`;ctx.textAlign=align;ctx.fillText(s,x,y)}
function drawScene(){if(!ctx||!world.width)return;ctx.setTransform(world.width/900,0,0,world.height/470,0,0);ctx.clearRect(0,0,900,470);if(state.scene==='home')drawHomeScene();else drawTravelScene()}
function drawHomeScene(){const f=family();let isBig=state.family==='ultra',isRich=state.family==='rich';let sky=ctx.createLinearGradient(0,0,0,410);sky.addColorStop(0,'#c7dfdf');sky.addColorStop(.63,'#e5e9d7');sky.addColorStop(1,'#d9e3cb');ctx.fillStyle=sky;ctx.fillRect(0,0,900,470);
  // soft clouds and distant hills
  ellipse(685,79,43,12,'#f3f5e8a8');ellipse(716,76,23,14,'#f3f5e8a8');ellipse(130,123,33,10,'#f3f5e8a0');
  poly([[0,230],[124,176],[267,224],[398,162],[548,225],[701,169],[900,220],[900,350],[0,350]],'#b7cfb1');poly([[0,263],[150,215],[285,261],[424,204],[584,256],[760,211],[900,258],[900,365],[0,365]],'#a7c69f');
  // yard and shadow
  poly([[36,316],[427,230],[864,319],[462,465]],'#91b47e');poly([[14,343],[433,255],[856,344],[468,470]],'#a4c690');
  // house footprint varies by tier
  let width=isBig?310:isRich?270:235,height=isBig?180:isRich?157:137;let hx=435,hy=250;let left=hx-width/2,top=hy-height;let roofTop=top-69;
  ellipse(hx+22,hy+92,width*.79,21,'#537b5940');
  // main house side walls
  poly([[left,top],[hx,top+44],[hx,hy+17],[left,hy-19]],isBig?'#d8d1c5':isRich?'#eee1ce':'#f1e8d8');poly([[hx,top+44],[left+width,top],[left+width,hy-18],[hx,hy+17]],isBig?'#aab5a5':isRich?'#d4c5ac':'#d3d9cc');
  // roof planes
  poly([[left-14,top+4],[hx,roofTop],[hx+10,top+25],[left+3,top+32]],isBig?'#53605a':isRich?'#685f64':'#63766b');poly([[hx,roofTop],[left+width+18,top+4],[hx+10,top+25]],isBig?'#758078':isRich?'#8b7b76':'#879488');
  // roof edge accents
  line(left-8,top+8,hx+8,roofTop+5,'#e0d9ca',2);line(hx+8,roofTop+5,left+width+10,top+8,'#d9d4c7',2);
  if(isBig){poly([[left+80,top+23],[left+80,top-28],[left+124,top-61],[left+169,top-28],[left+169,top+32]],'#758078');poly([[left+74,top-26],[left+124,top-67],[left+176,top-26]],'#53605a');}
  // windows and doors
  let winY=top+43;for(let i=0;i<(isBig?3:2);i++){let wx=left+35+i*69;rr(wx,winY,33,39,3,isBig?'#f0d99e':'#f5dca7');rr(wx+4,winY+4,25,30,2,'#9cc4c1');line(wx+16,winY+4,wx+16,winY+34,'#e3e1cc',2);line(wx+4,winY+19,wx+29,winY+19,'#e3e1cc',2)}
  for(let i=0;i<2;i++){let wx=hx+23+i*57;rr(wx,top+41,31,37,3,'#f4d99e');rr(wx+4,top+45,23,28,2,'#8fbab6');line(wx+15,top+46,wx+15,top+72,'#e3e3d1',2)}
  rr(hx-13,hy-8,34,61,3,'#8b6a51');rr(hx-8,hy-3,24,53,2,'#b38965');ellipse(hx+10,hy+24,2,2,'#f0d48b');
  // porch and steps
  poly([[hx-36,hy+51],[hx+45,hy+51],[hx+30,hy+60],[hx-45,hy+60]],'#e4dfcf');poly([[hx-27,hy+60],[hx+36,hy+60],[hx+24,hy+68],[hx-36,hy+68]],'#c8c8b7');
  // path to house
  poly([[hx-9,hy+58],[hx+19,hy+58],[hx+82,438],[hx+19,438]],'#d6cfba');
  for(let j=0;j<4;j++){let y=hy+77+j*32;poly([[hx+9,y],[hx+39,y],[hx+54,y+17],[hx+19,y+17]],'#c6c0aa')}
  // trees and shrubs
  drawTree(160,280,.95);drawTree(705,259,1.08);drawTree(790,300,.65);drawBush(300,342);drawBush(585,342);drawBush(388,355);
  // car and garden path
  drawCar(615,357,isBig?'#3f5050':isRich?'#7488a0':'#d28b59');drawFlower(214,353,'#f8cb82');drawFlower(746,374,'#ed9a87');drawFlower(270,385,'#f1e3a8');
  // character(s)
  const people=family().members;drawPerson(483,352,people[0].emoji,'#fff');drawPerson(521,365,people[1].emoji,'#e4f0e2');drawPerson(560,380,people[2].emoji,'#f6e1d4');
  if(state.family==='ultra'){drawPool(696,407)}
  // pale interaction tags
  drawTag(477,325,'YOUR FAMILY');drawTag(614,320,'FAMILY CAR');drawTag(434,210,isBig?'ESTATE':isRich?'CEDAR ESTATE':'HOME SWEET HOME');
  // sunlight flecks
  for(let i=0;i<9;i++){let x=(i*117+44)%900,y=85+(i*53)%220;ellipse(x,y,1.2,1.2,'#fff7c8')}
}
function drawTree(x,y,s=1){ellipse(x+3,y+3,22*s,8*s,'#54744d35');ctx.fillStyle='#826d50';ctx.fillRect(x-4*s,y-35*s,9*s,40*s);ellipse(x,y-48*s,24*s,27*s,'#70996d');ellipse(x-14*s,y-41*s,18*s,20*s,'#86aa76');ellipse(x+15*s,y-42*s,17*s,19*s,'#5f8e68');ellipse(x-4*s,y-61*s,15*s,16*s,'#91b97d')}
function drawBush(x,y){ellipse(x,y,26,10,'#698f62');ellipse(x-12,y-5,13,9,'#83a96e');ellipse(x+9,y-7,14,10,'#78a16a')}
function drawFlower(x,y,c){line(x,y,x,y-18,'#5d8a57',2);ellipse(x,y-19,4,4,c);ellipse(x-5,y-19,3,3,c);ellipse(x+5,y-19,3,3,c);ellipse(x,y-24,3,3,c);ellipse(x,y-14,3,3,c);ellipse(x,y-19,2,2,'#edcb67')}
function drawCar(x,y,color){ellipse(x+4,y+11,44,10,'#38543d40');poly([[x-40,y-3],[x-31,y-15],[x-11,y-22],[15,y-20],[34,y-8],[38,y+2],[29,y+7],[x-33,y+7]],color);poly([[x-25,y-14],[x-9,y-20],[12,y-19],[24,y-9],[x-29,y-8]],'#b9d1c9');line(x-4,y-19,x-1,y-8,'#eef0dc',2);ellipse(x-24,y+4,8,8,'#3b4541');ellipse(x+23,y+4,8,8,'#3b4541');ellipse(x-24,y+4,3.5,3.5,'#d8d7c6');ellipse(x+23,y+4,3.5,3.5,'#d8d7c6');rr(x+31,y-4,5,4,1,'#fff1c8')}
function drawPerson(x,y,emoji,shirt){ellipse(x,y+6,14,5,'#43634d36');ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText(emoji,x,y-3);rr(x-10,y+2,20,20,7,shirt);line(x-6,y+20,x-8,y+28,'#75624c',3);line(x+6,y+20,x+8,y+28,'#75624c',3)}
function drawTag(x,y,label){ctx.font='700 7px "DM Sans", sans-serif';let w=ctx.measureText(label).width+14;rr(x-w/2,y-9,w,15,7,'#ffffffbd');text(label,x,y+1,7,'#64776b','700')}
function drawPool(x,y){ellipse(x,y,48,18,'#477b7550');poly([[x-48,y-1],[x,y-17],[x+49,y-1],[x,y+16]],'#91c6c5');line(x-31,y,x,y+10,'#d0e7dc',1)}

function familyPicker(){openModal(`<div class="modal-kicker">A LIFE OF YOUR OWN</div><h2 id="modal-title">Which story will you tell?</h2><p class="modal-intro">Three households, three very different starting points. Every life is yours to shape.</p><div class="choice-grid">${Object.entries(families).map(([id,f])=>`<button class="choice-card ${state.family===id?'selected':''}" data-family="${id}"><span class="choice-icon">${f.icon}</span><strong>${f.name}</strong><small>${id==='average'?'Big dreams, modest beginnings.':id==='rich'?'Comfort, opportunity & room to grow.':'An extraordinary life with a world of choices.'}</small><span class="choice-funds">${fmt(f.funds)} to begin</span></button>`).join('')}</div><button class="modal-action" data-action="begin">Start this life <span>→</span></button><p class="modal-footnote">You can switch households any time. Your stories save separately.</p>`)}
function openTravel(){let city=state.destination||'Singapore';openModal(`<div class="modal-kicker">YOUR NEXT CHAPTER</div><h2 id="modal-title">Somewhere wonderful.</h2><p class="modal-intro">Pick a place, choose how you fly, and go make a memory. All fares are round-trip for your household.</p><div class="destination-grid">${destinations.map(([name,flag,price,copy])=>`<button class="destination ${city===name?'selected':''}" data-city="${name}"><span class="city-emoji">${flag}</span><strong>${name}</strong><small>${copy} · from ${price}</small></button>`).join('')}</div><div class="class-options">${classes.map((c,i)=>`<button class="class-option ${state.travelClass===i?'selected':''}" data-class="${i}"><strong>${c.icon} ${c.name}</strong><small>${c.copy}</small></button>`).join('')}</div><label class="select-label" for="trip-length">How long are we away?</label><select class="select-control" id="trip-length"><option value="3" ${state.tripDays===3?'selected':''}>A long weekend · 3 days</option><option value="5" ${state.tripDays===5?'selected':''}>Just right · 5 days</option><option value="7" ${state.tripDays===7?'selected':''}>A whole week · 7 days</option></select><div class="trip-summary"><span id="trip-flight-type">${family().plane} · ${family().members.length} travelers</span><b id="trip-price">${fmt(tripCost(city,state.travelClass))}</b></div><button class="modal-action" data-action="fly">Book this getaway <span>✈</span></button><p class="modal-footnote">Your fares include the whole household. Holiday memories: priceless.</p>`)}
function tripCost(city,cl){let item=destinations.find(d=>d[0]===city)||destinations[0];let base=dollars(item[2]);let people=family().members.length+state.peopleExtra.length;let planeFactor=state.family==='ultra'?.58:state.family==='rich'?.82:1;return Math.ceil(base*classes[cl].mult*people*planeFactor)}
function openCareer(){let f=family(),careerCost=[500,3500,18000][Math.min(state.careerLevel,2)],businessCost=[1800,12000,150000][state.family==='average'?0:state.family==='rich'?1:2];openModal(`<div class="modal-kicker">WORK & OPPORTUNITY</div><h2 id="modal-title">Make your next move.</h2><p class="modal-intro">Build a career, grow a business, and see what your household can do.</p><div class="modal-section"><h4>💼 Career · ${f.job}</h4><p>Current household income is ${fmt(f.income)} per month. A little ambition can make a big difference.</p><div class="option-row"><span>Take the next step <small style="color:#929a94"> · one-time ${fmt(careerCost)}</small></span><button data-action="promote">${state.careerLevel>=3?'Max level':`Grow career · ${fmt(careerCost)}`}</button></div><div class="option-row"><span>Current business</span><strong>${f.business}</strong></div><div class="option-row"><span>Start or expand a business</span><button data-action="business">${state.businessLevel?'Expand · ': 'Start · '}${fmt(businessCost)}</button></div></div><div class="stats-grid"><div class="stat-tile"><small>Work-life balance</small><strong>${Math.max(52,82-state.careerLevel*5)}%</strong></div><div class="stat-tile"><small>Career momentum</small><strong>${['Growing','On the rise','Established','Leading'][Math.min(state.careerLevel,3)]}</strong></div></div><p class="modal-footnote">Better opportunities take a little time, and a little investment.</p>`)}
function openAssets(){let f=family();let carCosts=[6500,42000,480000],insCosts=[190,850,4500];let carLabels=['A safer family car','A little more luxury','The dream garage'];let cover=['Better home & health','Premium full coverage','All-assets protection'];let ci=Math.min(state.vehicleLevel,2),ii=Math.min(state.insuranceLevel,2);openModal(`<div class="modal-kicker">WHAT YOU OWN, WHAT YOU PROTECT</div><h2 id="modal-title">The practical little things.</h2><p class="modal-intro">Your home, vehicle, and coverage start out selected for your family's means. Upgrade when it feels right.</p><div class="modal-section"><h4>⌂ Home & neighborhood</h4><div class="option-row"><span>Your ${f.homeStyle} home · ${f.neighborhood}</span><strong>${fmt(f.home)}</strong></div><div class="option-row"><span>Make the home a little nicer</span><button data-action="home-upgrade">Add a home touch · ${fmt(Math.ceil(f.home*.012))}</button></div></div><div class="modal-section"><h4>🚗 Getting around</h4><div class="option-row"><span>${state.vehicleLevel?['Used hatchback','Electric grand tourer','Luxury car collection'][ci]:f.vehicle}</span><button data-action="car">${state.vehicleLevel>=2?'Collection ready':`${carLabels[ci]} · ${fmt(carCosts[ci])}`}</button></div><div class="option-row"><span>Travel style</span><strong>${f.plane}</strong></div></div><div class="modal-section"><h4>♡ A little peace of mind</h4><div class="option-row"><span>${state.insuranceLevel?cover[ii]:f.insurance}</span><button data-action="insurance">${state.insuranceLevel>=2?'Fully covered':`${cover[ii]} · ${fmt(insCosts[ii])}/mo`}</button></div><p>Health, home & vehicle cover protect your household when life surprises you.</p></div>`)}
function openFamily(){let extra=state.peopleExtra.length;openModal(`<div class="modal-kicker">YOUR PEOPLE, YOUR STORY</div><h2 id="modal-title">A little life together.</h2><p class="modal-intro">Everyone in your household has a story, a role, and room to grow.</p><div class="modal-section">${family().members.concat(state.peopleExtra).map(p=>`<div class="option-row"><span>${p.emoji} &nbsp;${p.name}<small style="color:#929a94"> · ${p.role}</small></span><strong>${p.status}</strong></div>`).join('')}</div><div class="modal-section"><h4>Household rhythm</h4><p>Take care of each other and celebrate the little wins. Every day can make your shared goal a bit closer.</p><div class="option-row"><span>Everyone's mood today</span><strong>${state.mood}% · feeling good</strong></div></div><button class="modal-action" data-action="family-goal">Spend a day together · $150</button>`)}
function openHome(){openModal(`<div class="modal-kicker">${family().neighborhood.toUpperCase()} · YOUR HOME</div><h2 id="modal-title">A place to put down roots.</h2><p class="modal-intro">This is where your days begin. Fill it with the things that make it yours.</p><div class="stats-grid"><div class="stat-tile"><small>Home value</small><strong>${fmt(family().home)}</strong></div><div class="stat-tile"><small>Neighborhood</small><strong>${family().neighborhood}</strong></div></div><div class="modal-section"><h4>At home today</h4><p>${family().members.map(p=>p.name.split(' ')[0]).join(', ')} are making this place feel like home.</p></div><div class="option-row"><span>Decorate & add a little comfort</span><button data-action="home-upgrade">${fmt(Math.ceil(family().home*.012))}</button></div><button class="modal-action" data-action="family-goal">Have a family afternoon · $150</button>`)}
function openPanel(panel){document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.panel===panel));if(panel==='home')openHome();if(panel==='family')openFamily();if(panel==='career')openCareer();if(panel==='assets')openAssets();if(panel==='travel')openTravel()}

