1: function familyPicker(){openModal(`<div class="modal-kicker">A LIFE OF YOUR OWN</div><h2 id="modal-title">Which story will you tell?</h2><p class="modal-intro">Three households, three very different starting points. Every life is yours to shape.</p><div class="choice-grid">${Object.entries(families).map(([id,f])=>`<button class="choice-card ${state.family===id?'selected':''}" data-family="${id}"><span class="choice-icon">${f.icon}</span><strong>${f.name}</strong><small>${id==='average'?'Big dreams, modest beginnings.':id==='rich'?'Comfort, opportunity & room to grow.':'An extraordinary life with a world of choices.'}</small><span class="choice-funds">${fmt(f.funds)} to begin</span></button>`).join('')}</div><button class="modal-action" data-action="begin">Start this life <span>→</span></button><p class="modal-footnote">You can switch households any time. Your stories save separately.</p>`)}
2: function openTravel(){let city=state.destination||'Singapore';openModal(`<div class="modal-kicker">YOUR NEXT CHAPTER</div><h2 id="modal-title">Somewhere wonderful.</h2><p class="modal-intro">Pick a place, choose how you fly, and go make a memory. All fares are round-trip for your household.</p><div class="destination-grid">${destinations.map(([name,flag,price,copy])=>`<button class="destination ${city===name?'selected':''}" data-city="${name}"><span class="city-emoji">${flag}</span><strong>${name}</strong><small>${copy} · from ${price}</small></button>`).join('')}</div><div class="class-options">${classes.map((c,i)=>`<button class="class-option ${state.travelClass===i?'selected':''}" data-class="${i}"><strong>${c.icon} ${c.name}</strong><small>${c.copy}</small></button>`).join('')}</div><label class="select-label" for="trip-length">How long are we away?</label><select class="select-control" id="trip-length"><option value="3" ${state.tripDays===3?'selected':''}>A long weekend · 3 days</option><option value="5" ${state.tripDays===5?'selected':''}>Just right · 5 days</option><option value="7" ${state.tripDays===7?'selected':''}>A whole week · 7 days</option></select><div class="trip-summary"><span id="trip-flight-type">${family().plane} · ${family().members.length} travelers</span><b id="trip-price">${fmt(tripCost(city,state.travelClass))}</b></div><button class="modal-action" data-action="fly">Book this getaway <span>✈</span></button><p class="modal-footnote">Your fares include the whole household. Holiday memories: priceless.</p>`)}
3: function tripCost(city,cl){let item=destinations.find(d=>d[0]===city)||destinations[0];let base=dollars(item[2]);let people=family().members.length+state.peopleExtra.length;let planeFactor=state.family==='ultra'?.58:state.family==='rich'?.82:1;return Math.ceil(base*classes[cl].mult*people*planeFactor)}
4: function openCareer(){let f=family(),careerCost=[500,3500,18000][Math.min(state.careerLevel,2)],businessCost=[1800,12000,150000][state.family==='average'?0:state.family==='rich'?1:2];openModal(`<div class="modal-kicker">WORK & OPPORTUNITY</div><h2 id="modal-title">Make your next move.</h2><p class="modal-intro">Build a career, grow a business, and see what your household can do.</p><div class="modal-section"><h4>💼 Career · ${f.job}</h4><p>Current household income is ${fmt(f.income)} per month. A little ambition can make a big difference.</p><div class="option-row"><span>Take the next step <small style="color:#929a94"> · one-time ${fmt(careerCost)}</small></span><button data-action="promote">${state.careerLevel>=3?'Max level':`Grow career · ${fmt(careerCost)}`}</button></div><div class="option-row"><span>Current business</span><strong>${f.business}</strong></div><div class="option-row"><span>Start or expand a business</span><button data-action="business">${state.businessLevel?'Expand · ': 'Start · '}${fmt(businessCost)}</button></div></div><div class="stats-grid"><div class="stat-tile"><small>Work-life balance</small><strong>${Math.max(52,82-state.careerLevel*5)}%</strong></div><div class="stat-tile"><small>Career momentum</small><strong>${['Growing','On the rise','Established','Leading'][Math.min(state.careerLevel,3)]}</strong></div></div><p class="modal-footnote">Better opportunities take a little time, and a little investment.</p>`)}
5: function openAssets(){let f=family();let carCosts=[6500,42000,480000],insCosts=[190,850,4500];let carLabels=['A safer family car','A little more luxury','The dream garage'];let cover=['Better home & health','Premium full coverage','All-assets protection'];let ci=Math.min(state.vehicleLevel,2),ii=Math.min(state.insuranceLevel,2);openModal(`<div class="modal-kicker">WHAT YOU OWN, WHAT YOU PROTECT</div><h2 id="modal-title">The practical little things.</h2><p class="modal-intro">Your home, vehicle, and coverage start out selected for your family's means. Upgrade when it feels right.</p><div class="modal-section"><h4>⌂ Home & neighborhood</h4><div class="option-row"><span>Your ${f.homeStyle} home · ${f.neighborhood}</span><strong>${fmt(f.home)}</strong></div><div class="option-row"><span>Make the home a little nicer</span><button data-action="home-upgrade">Add a home touch · ${fmt(Math.ceil(f.home*.012))}</button></div></div><div class="modal-section"><h4>🚗 Getting around</h4><div class="option-row"><span>${state.vehicleLevel?['Used hatchback','Electric grand tourer','Luxury car collection'][ci]:f.vehicle}</span><button data-action="car">${state.vehicleLevel>=2?'Collection ready':`${carLabels[ci]} · ${fmt(carCosts[ci])}`}</button></div><div class="option-row"><span>Travel style</span><strong>${f.plane}</strong></div></div><div class="modal-section"><h4>♡ A little peace of mind</h4><div class="option-row"><span>${state.insuranceLevel?cover[ii]:f.insurance}</span><button data-action="insurance">${state.insuranceLevel>=2?'Fully covered':`${cover[ii]} · ${fmt(insCosts[ii])}/mo`}</button></div><p>Health, home & vehicle cover protect your household when life surprises you.</p></div>`)}
6: function openFamily(){let extra=state.peopleExtra.length;openModal(`<div class="modal-kicker">YOUR PEOPLE, YOUR STORY</div><h2 id="modal-title">A little life together.</h2><p class="modal-intro">Everyone in your household has a story, a role, and room to grow.</p><div class="modal-section">${family().members.concat(state.peopleExtra).map(p=>`<div class="option-row"><span>${p.emoji} &nbsp;${p.name}<small style="color:#929a94"> · ${p.role}</small></span><strong>${p.status}</strong></div>`).join('')}</div><div class="modal-section"><h4>Household rhythm</h4><p>Take care of each other and celebrate the little wins. Every day can make your shared goal a bit closer.</p><div class="option-row"><span>Everyone's mood today</span><strong>${state.mood}% · feeling good</strong></div></div><button class="modal-action" data-action="family-goal">Spend a day together · $150</button>`)}
7: function openHome(){openModal(`<div class="modal-kicker">${family().neighborhood.toUpperCase()} · YOUR HOME</div><h2 id="modal-title">A place to put down roots.</h2><p class="modal-intro">This is where your days begin. Fill it with the things that make it yours.</p><div class="stats-grid"><div class="stat-tile"><small>Home value</small><strong>${fmt(family().home)}</strong></div><div class="stat-tile"><small>Neighborhood</small><strong>${family().neighborhood}</strong></div></div><div class="modal-section"><h4>At home today</h4><p>${family().members.map(p=>p.name.split(' ')[0]).join(', ')} are making this place feel like home.</p></div><div class="option-row"><span>Decorate & add a little comfort</span><button data-action="home-upgrade">${fmt(Math.ceil(family().home*.012))}</button></div><button class="modal-action" data-action="family-goal">Have a family afternoon · $150</button>`)}
8: function openPanel(panel){document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.panel===panel));if(panel==='home')openHome();if(panel==='family')openFamily();if(panel==='career')openCareer();if(panel==='assets')openAssets();if(panel==='travel')openTravel()}

