function resizeCanvas(){const r=world.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);if(!r.width||!r.height)return;world.width=Math.round(r.width*dpr);world.height=Math.round(r.height*dpr);world.style.width=r.width+'px';world.style.height=r.height+'px';drawScene()}
function modalShell(kicker,title,copy,body,footer=''){openModal(`<div class="eyebrow">${kicker}</div><h2 class="modal-title" id="modal-title">${title}</h2><p class="modal-copy">${copy}</p>${body}${footer?`<div class="modal-footer">${footer}</div>`:''}`)}
function actionButton(label,action,style='primary',attrs=''){return `<button class="action-btn ${style}" data-action="${action}" ${attrs}>${label}</button>`}
function openFamilyPicker(){let cards=Object.entries(families).map(([id,f])=>`<button class="family-choice ${id===state.family?'chosen':''}" data-action="switch-family" data-family="${id}"><span class="choice-icon">${f.icon}</span><span><b>${f.name}</b><small>${f.neighborhood} · ${fmt(f.funds)} starting funds</small></span><span class="choice-check">${id===state.family?'✓':'→'}</span></button>`).join('');modalShell('CHOOSE YOUR STORY','A new chapter','Switching households starts their saved story at its current point.',`<div class="choice-list">${cards}</div>`)}
function openPanel(panel){
 const f=family();
 if(panel==='family'){
  const people=f.members.concat(state.peopleExtra).map(p=>`<div class="modal-person"><span>${p.emoji}</span><div><b>${p.name}</b><small>${p.role} · ${p.status}</small></div></div>`).join('');
  modalShell('YOUR PEOPLE','Life is better together',`Meet the ${f.name} household and make room for a new chapter.`,`<div class="modal-list">${people}</div><div class="soft-note">Household mood: <b>${state.mood}%</b> · everyone is doing pretty well.</div>`,actionButton('Welcome someone new · $2,500','add-person'));
 }else if(panel==='career'){
  let careerCost=Math.round(1500*Math.pow(1.7,state.careerLevel)),businessCost=Math.round(4500*Math.pow(1.8,state.businessLevel));
  modalShell('CAREER & BUSINESS','Build what comes next',`Your work today shapes the choices your family can make tomorrow.`,`<div class="upgrade-card"><span class="upgrade-icon">↗</span><div><b>${f.job}</b><small>Monthly household income: ${fmt(f.income)} · Career level ${state.careerLevel+1}</small></div><strong>${fmt(careerCost)}</strong></div><div class="upgrade-card"><span class="upgrade-icon">⌂</span><div><b>${f.business}</b><small>Grow your business and unlock new opportunities</small></div><strong>${fmt(businessCost)}</strong></div>`,`${actionButton('Invest in career','career-up')} ${actionButton('Grow business','business-up','secondary')}`);
 }else if(panel==='assets'){
  const upgrades=[['vehicle','Upgrade vehicle',f.vehicle,Math.round((f.wealth<40?12000:75000)*Math.pow(1.8,state.vehicleLevel)),state.vehicleLevel],['insurance','Improve protection',f.insurance,Math.round((f.wealth<40?1800:14000)*Math.pow(1.7,state.insuranceLevel)),state.insuranceLevel]];
  let rows=upgrades.map(([key,label,desc,cost,level])=>`<div class="upgrade-card"><span class="upgrade-icon">${key==='vehicle'?'◇':'♡'}</span><div><b>${label}</b><small>${desc} · level ${level+1}</small></div><strong>${fmt(cost)}</strong><button class="mini-buy" data-action="${key}-up">Choose</button></div>`).join('');
  modalShell('ASSETS & COVER','Care for the things you love','Vehicles and insurance make everyday life a little more secure.',`<div class="asset-summary"><span>Home</span><b>${fmt(f.home)}</b><span>Travel</span><b>${f.plane}</b></div><div class="modal-list">${rows}</div>`);
 }else if(panel==='travel'){
  if(state.scene==='travel'){
   modalShell('AWAY TOGETHER',`${state.destination} is yours to explore`,`You have ${Math.max(0,state.tripDays)} vacation day${state.tripDays===1?'':'s'} left. Make a memory, or head home whenever you like.`,`<div class="soft-note">${state.travelClass===0?'Economy':state.travelClass===1?'Business':'First class'} · ${family().members.length+state.peopleExtra.length} traveler(s)</div>`,`${actionButton('Spend a day exploring','explore-day')} ${actionButton('Return home','return-home','secondary')}`);return;
  }
  let destinationCards=destinations.map((d,i)=>`<button class="destination-choice ${state.destination===d[0]?'chosen':''}" data-action="destination" data-index="${i}"><span class="flag">${d[1]}</span><span><b>${d[0]}</b><small>${d[3]}</small></span><span class="choice-check">${state.destination===d[0]?'✓':'→'}</span></button>`).join('');
  const cls=classes.map((c,i)=>`<button class="class-choice ${state.travelClass===i?'chosen':''}" data-action="travel-class" data-index="${i}"><b>${c.icon} ${c.name}</b><small>${c.copy} · ×${c.mult}</small></button>`).join('');
  let selected=destinations.find(d=>d[0]===state.destination),base=selected?dollars(selected[2]):980,price=Math.round(base*classes[state.travelClass].mult*(family().members.length+state.peopleExtra.length));
  modalShell('TRAVEL THE WORLD','Where shall life take you?',`Pick a destination and cabin for a ${state.tripDays}-day family getaway. Tickets are priced per traveler.`,`<div class="destination-grid">${destinationCards}</div><div class="class-grid">${cls}</div><label class="trip-length">Trip length <select id="trip-length"><option value="3" ${state.tripDays===3?'selected':''}>3 days</option><option value="5" ${state.tripDays===5?'selected':''}>5 days</option><option value="7" ${state.tripDays===7?'selected':''}>7 days</option></select></label><div class="price-line"><span>Estimated round-trip total</span><b>${selected?fmt(price):'Choose a destination'}</b></div>`,actionButton(`Book this getaway${selected?` · ${fmt(price)}`:''}`,'book-trip'));
 }else if(panel==='home'){
  modalShell('WELCOME HOME',`${f.name} home`,`A ${f.homeStyle} home in ${f.neighborhood}. What would you like to do today?`,`<div class="soft-note">Home value ${fmt(f.home)} · ${f.vehicle} · ${f.insurance}</div>`,`${actionButton('Spend time together','family-time')} ${actionButton('Plan a getaway','open-travel','secondary')}`);
 }
}

