function refresh(){sync();save()}
function selectFamily(id){if(!families[id])return;state.householdMoney=state.householdMoney||{};state.householdMoney[state.family]=state.money;state.family=id;state.money=state.householdMoney[id]??families[id].funds;selectedFamily=id;state.scene='home';state.destination=null;state.peopleExtra=state.peopleExtra||[];closeModal();refresh();toast(`${families[id].name} are ready for a new day.`)}
function nextDay(){
 state.day++;if(state.day>30){state.day=1;state.month++;if(state.month>12){state.month=1;state.year++}}
 if(state.scene==='home'){
  const pay=family().income/30;state.money+=pay;state.mood=Math.min(100,state.mood+1);state.goalProgress=Math.min(100,state.goalProgress+(Math.random()<.48?1:0));toast(`A new day begins. ${fmt(pay)} household income received.`)
 }else{
  state.tripDays--;state.day++;
  const daily=Math.max(80,Math.round((family().wealth<40?150:family().wealth<80?650:2600)*(family().members.length+state.peopleExtra.length)));
  state.money=Math.max(0,state.money-daily);state.mood=Math.min(100,state.mood+2);state.goalProgress=Math.min(100,state.goalProgress+2);
  if(state.tripDays<=0){state.scene='home';state.destination=null;toast('Welcome home! Your family has lovely new memories.')}
  else toast(`Day ${state.day} of your getaway. ${fmt(daily)} spent on today's adventures.`)
 }
 refresh();if($('#modal-backdrop').classList.contains('open'))openPanel('travel')
}
function buyUpgrade(type){let cost,key,success;
 if(type==='career'){cost=Math.round(1500*Math.pow(1.7,state.careerLevel));if(!spend(cost))return;state.careerLevel++;families[state.family].income=Math.round(family().income*1.16);success='A new opportunity is opening up.'}
 else if(type==='business'){cost=Math.round(4500*Math.pow(1.8,state.businessLevel));if(!spend(cost))return;state.businessLevel++;families[state.family].income=Math.round(family().income*1.22);success='Your business is growing.'}
 else if(type==='vehicle'){cost=Math.round((family().wealth<40?12000:75000)*Math.pow(1.8,state.vehicleLevel));if(!spend(cost))return;state.vehicleLevel++;success='A fresh set of keys! Your vehicle is upgraded.'}
 else{cost=Math.round((family().wealth<40?1800:14000)*Math.pow(1.7,state.insuranceLevel));if(!spend(cost))return;state.insuranceLevel++;success='Your family has more peace of mind.'}
 state.mood=Math.min(100,state.mood+2);refresh();toast(success);openPanel(type==='career'||type==='business'?'career':'assets')
}
function addPerson(){if(!spend(2500))return;const picks=[['Jamie Moreau','Family friend','🧑🏻'],['Avery Lane','Cousin · always visiting','🧑🏽'],['Robin Ellis','New little sibling','👶🏻']];let p=picks[state.peopleExtra.length%picks.length];state.peopleExtra.push({name:p[0],role:p[1],emoji:p[2],status:'At home',initial:p[0][0]});state.mood=Math.min(100,state.mood+5);state.goalProgress=Math.min(100,state.goalProgress+4);refresh();toast('Your household has a new loved one.');openPanel('family')}
function bookTrip(){if(!state.destination){toast('Choose a destination first.');return}const d=destinations.find(x=>x[0]===state.destination),people=family().members.length+state.peopleExtra.length,cost=Math.round(dollars(d[2])*classes[state.travelClass].mult*people);if(!spend(cost))return;state.scene='travel';state.day=1;closeModal();refresh();toast(`Tickets booked to ${state.destination}! Have a wonderful trip.`)}
function handleAction(action,el){
 if(action==='switch-family'){selectFamily(el.dataset.family);return}
 if(action==='destination'){state.destination=destinations[Number(el.dataset.index)][0];openPanel('travel');return}
 if(action==='travel-class'){state.travelClass=Number(el.dataset.index);openPanel('travel');return}
 if(action==='book-trip'){let sel=$('#trip-length');if(sel)state.tripDays=Number(sel.value);bookTrip();return}
 if(action==='open-travel'){closeModal();openPanel('travel');return}
 if(action==='return-home'){state.scene='home';state.destination=null;state.tripDays=5;closeModal();refresh();toast('Back home, with stories to tell.');return}
 if(action==='explore-day'){closeModal();nextDay();return}
 if(action==='career-up'||action==='business-up'||action==='vehicle-up'||action==='insurance-up'){buyUpgrade(action.replace('-up',''));return}
 if(action==='add-person'){addPerson();return}
 if(action==='family-time'){if(!spend(100,'A little time together goes a long way.'))return;state.mood=Math.min(100,state.mood+8);state.goalProgress=Math.min(100,state.goalProgress+8);refresh();closeModal();return}
}
function bindEvents(){
 document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n===b));openPanel(b.dataset.panel)}));
 $('#family-avatar').addEventListener('click',openFamilyPicker);$('#next-day').addEventListener('click',nextDay);$('#open-home').addEventListener('click',()=>openPanel(state.scene==='home'?'home':'travel'));$('#add-person').addEventListener('click',addPerson);$('#goals-expand').addEventListener('click',()=>modalShell('LITTLE BY LITTLE','A goal worth growing',`Every good life is built one day at a time.`,`<div class="soft-note"><b>${family().goal}</b><br>${state.goalProgress}% complete. Spend time together or explore a new place to make progress.</div>`,actionButton('Spend time together','family-time')));$('#new-goal').addEventListener('click',()=>{const goals=['Make this house a home','Grow the family portfolio','Leave a brighter legacy','Plan a family adventure','Create more time together'];let i=(goals.indexOf(family().goal)+1)%goals.length;family().goal=goals[i];family().goalSub='A little step at a time';state.goalProgress=10;refresh();toast(`New goal set: ${family().goal}`)});
 $('#zoom-in').addEventListener('click',()=>{state.zoom=Math.min(1.35,state.zoom+.1);drawScene()});$('#zoom-out').addEventListener('click',()=>{state.zoom=Math.max(.85,state.zoom-.1);drawScene()});$('#view-toggle').addEventListener('click',()=>{state.zoom=state.zoom===1?1.18:1;drawScene()});$('#modal-close').addEventListener('click',closeModal);$('#modal-backdrop').addEventListener('click',e=>{if(e.target.id==='modal-backdrop')closeModal()});$('#modal-content').addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b)handleAction(b.dataset.action,b)});
 $('#world').addEventListener('click',e=>{let r=world.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*900,y=(e.clientY-r.top)/r.height*470;if(state.scene==='home'&&y>300&&x>430&&x<590)openPanel('family');else if(state.scene==='home'&&x>570&&y>300)openPanel('assets');else openPanel(state.scene==='home'?'home':'travel')});window.addEventListener('resize',resizeCanvas);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});$('#sound-toggle').addEventListener('click',()=>toast('A peaceful little world, just as it is.'));
}
function init(){state.peopleExtra=state.peopleExtra||[];state.householdMoney=state.householdMoney||{};if(state.householdMoney[state.family]==null)state.householdMoney[state.family]=state.money;state.zoom=Number(state.zoom)||1;bindEvents();sync();requestAnimationFrame(resizeCanvas)}
init();

