content.text:
.modal-backdrop{display:none;position:fixed;inset:0;background:#17231e75;backdrop-filter:blur(4px);z-index:20;align-items:center;justify-content:center;padding:18px}
.modal-backdrop.open{display:flex}
.modal{position:relative;background:#fbfaf7;width:min(560px,100%);max-height:min(88vh,780px);overflow:auto;border-radius:16px;padding:30px;box-shadow:0 24px 80px #10201540;animation:modal-in .22s ease-out}
.modal-close{position:absolute;right:16px;top:14px;border:0;background:#f0f0eb;border-radius:50%;width:28px;height:28px;font-size:20px;color:#6d766f;cursor:pointer}
.modal-kicker{font-size:9px;letter-spacing:1.5px;color:#7e9a80;font-weight:700}
.modal h2{font:700 24px var(--display);letter-spacing:-1px;margin:7px 0 6px}
.modal-intro{font-size:11px;line-height:1.6;color:#89918a;margin:0 0 19px}
.modal-action{display:block;width:100%;height:42px;border:0;border-radius:8px;background:#537b61;color:white;font:700 11px var(--sans);cursor:pointer;margin-top:16px;transition:.18s}
.modal-action:hover{background:#426b51}
.modal-action:disabled{background:#c9d1c8;color:#fff;cursor:not-allowed}
.modal-footnote{text-align:center;color:#9ca39c;font-size:8px;margin:10px 0 0}
.modal-section{background:#fff;border:1px solid #eeefea;border-radius:10px;padding:13px 15px;margin-top:9px}
.modal-section h4{font-size:10px;margin:0 0 5px}
.modal-section p{color:#8f9790;font-size:9px;line-height:1.55;margin:0}
.toast{position:fixed;bottom:22px;left:50%;transform:translate(-50%,20px);background:#263b2d;color:white;padding:11px 16px;border-radius:9px;font-size:10px;box-shadow:0 8px 25px #16251b33;opacity:0;pointer-events:none;transition:.25s;z-index:30}
.toast.show{opacity:1;transform:translate(-50%,0)}
.modal{padding:25px 18px 18px;border-radius:14px}
.modal h2{font-size:21px}

