72: function income(){return Math.round(family().income*Math.pow(1.16,state.careerLevel||0)*Math.pow(1.22,state.businessLevel||0))}
73: function refresh(){sync();state.householdMoney=state.householdMoney||{};state.householdLevels=state.householdLevels||{};state.householdMoney[state.family]=state.money;state.householdLevels[state.family]={careerLevel:state.careerLevel,businessLevel:state.businessLevel,insuranceLevel:state.insuranceLevel,vehicleLevel:state.vehicleLevel};save()}
74: function selectFamily(id){if(!families[id])return;state.householdMoney=state.householdMoney||{};state.householdLevels=state.householdLevels||{};state.householdMoney[state.family]=state.money;state.householdLevels[state.family]={careerLevel:state.careerLevel,businessLevel:state.businessLevel,insuranceLevel:state.insuranceLevel,vehicleLevel:state.vehicleLevel};state.family=id;state.money=state.householdMoney[id]??families[id].funds;Object.assign(state,{careerLevel:0,businessLevel:0,insuranceLevel:0,vehicleLevel:0},state.householdLevels[id]||{});selectedFamily=id;state.scene='home';state.destination=null;state.peopleExtra=[];closeModal();refresh();toast(`${families[id].name} are ready for a new day.`)}
