90:  else if(type==='business'){cost=Math.round(4500*Math.pow(1.8,state.businessLevel));if(!spend(cost))return;state.businessLevel++;success='Your business is growing.'}
91:  else if(type==='vehicle'){cost=Math.round((family().wealth<40?12000:75000)*Math.pow(1.8,state.vehicleLevel));if(!spend(cost))return;state.vehicleLevel++;success='A fresh set of keys! Your vehicle is upgraded.'}
92:  else{cost=Math.round((family().wealth<40?1800:14000)*Math.pow(1.7,state.insuranceLevel));if(!spend(cost))return;state.insuranceLevel++;success='Your family has more peace of mind.'}
93:  state.mood=Math.min(100,state.mood+2);refresh();toast(success);openPanel(type==='career'||type==='business'?'career':'assets')
