95: function addPerson(){if(!spend(2500))return;const picks=[['Jamie Moreau','Family friend','🧑🏻'],['Avery Lane','Cousin · always visiting','🧑🏽'],['Robin Ellis','New little sibling','👶🏻']];let p=picks[state.peopleExtra.length%picks.length];state.peopleExtra.push({name:p[0],role:p[1],emoji:p[2],status:'At home',initial:p[0][0]});state.mood=Math.min(100,state.mood+5);state.goalProgress=Math.min(100,state.goalProgress+4);refresh();toast('Your household has a new loved one.');openPanel('family')}
96: function bookTrip(){if(!state.destination){toast('Choose a destination first.');return}const d=destinations.find(x=>x[0]===state.destination),people=family().members.length+state.peopleExtra.length,cost=Math.round(dollars(d[2])*classes[state.travelClass].mult*people);if(!spend(cost))return;state.scene='travel';state.day=1;closeModal();refresh();toast(`Tickets booked to ${state.destination}! Have a wonderful trip.`)}
97: function handleAction(action,el){
98:  if(action==='switch-family'){selectFamily(el.dataset.family);return}
99:  if(action==='destination'){state.destination=destinations[Number(el.dataset.index)][0];openPanel('travel');return}
100:  if(action==='travel-class'){state.travelClass=Number(el.dataset.index);openPanel('travel');return}
101:  if(action==='book-trip'){let sel=$('#trip-length');if(sel)state.tripDays=Number(sel.value);bookTrip();return}
